public class Two {
    public static <K> void main(String[] args) throws Exception {
        BufferedWriter br = new BufferedWriter(new FileWriter(new File("/home/vignesh/Desktop/data.txt")));
        Map<Long, String> map = new HashMap<>();
        Scanner sc = new Scanner(System.in);
        int c = 0;
        long key;
        String value;
        while (c <= 1) {
            System.out.println(" enter the key");
            key = sc.nextLong();
            System.out.println("enter the value");
            value = sc.next();
            if (num(key) && rev(value))
                map.put(key, value);
            c++;
        }
        int c1 = 1;
        for (Entry<Long, String> m : map.entrySet()) {
            br.write(m.getKey() + "=");
            br.write(m.getValue() + "");
            if (c1 < map.size() - 1) {
                br.write(",");
            } else {
                br.write(".");
            }
            br.write("\n");
            c1++;
        }
        br.flush();
        br.close();
        System.out.println(map + "" + map.size());
    }

    public static boolean num(long key) {
        if (key % 2 != 0)
            return false;
        while (key > 0) {
            if ((key % 10) % 2 != 0)
                return false;
            key /= 10;
        }
        return true;
    }

    public static boolean rev(String value) {
        String s = "";
        if (value.length() <= 6) {
            for (int i = value.length() - 1; i >= 0; i--) {
                s += value.charAt(i);
            }
            return s.equals(value) ? true : false;
        } else {
            return false;
        }
    }
}


